"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4826],{34826:a=>{a.exports=JSON.parse('{"slug":"kurs-dollara-nizhe-83-rubley-nalogovyy-period-oktyabr-2026","locale":"ru","title":"Доллар опустился ниже 83 рублей впервые с августа, несмотря на крупнейшие с 2022 года покупки валюты","description":"Официальный курс доллара на 20 октября 82,85 рубля, минимум с августа. Почему рубль крепнет перед налогами 28 октября, хотя Минфин скупает валюту.","blocks":[{"id":"b001","kind":"paragraph","text":"Банк России установил официальный курс доллара на 20 октября на уровне 82,85 рубля, на 77 копеек ниже предыдущего. Ниже 83 он не опускался с 22 августа. Евро подешевел до 93,23 рубля, юань до 12,39. На внебиржевом рынке 19 октября доллар доходил до 82,56 рубля. В начале месяца было наоборот: 7 октября официальный курс поднимался до 85,71 рубля. За 2 недели рубль отыграл это ослабление."},{"id":"b002","kind":"paragraph","text":"Ослабление 7 октября объясняли покупками валюты по бюджетному правилу. Сверхдоходы от дорогой нефти Минфин откладывает в Фонд национального благосостояния, покупая валюту и золото. С 7 октября по 6 ноября он тратит на это 279,42 млрд рублей. С учётом продаж Банка России государство покупает 12,1 млрд рублей в день. Это в 6 раз больше, чем в сентябре, и больше всего с января 2022 года."},{"id":"b003","kind":"paragraph","text":"Представим фрилансера, которому платят в долларах, а квартплату нужно внести в рублях до 28-го числа. Всю первую половину месяца он держит доллары, а за неделю до срока продаёт сразу крупную сумму. Экспортёры живут так же. Срок уплаты налогов за сентябрь 28 октября. Нефтегазовые доходы бюджета в октябре оцениваются примерно в 1 трлн рублей, на 0,5 трлн больше, чем в сентябре. Разница во многом приходится на квартальный налог на дополнительный доход, около 0,36 трлн. Поэтому вторую половину месяца на бирже называют налоговым периодом."},{"id":"b004","kind":"paragraph","text":"Аналитики оценивают продажи валюты крупнейшими экспортёрами в октябре примерно в $4 млрд. Покупки государства за месяц при нынешнем курсе стоят около $3,2 млрд и растянуты равными частями на 22 торговых дня. В результате к концу месяца предложение валюты обгоняет спрос. Рублю помогли и внешние факторы. Индекс доллара к мировым валютам 19 октября опустился на 1,2% от недавнего максимума, а США отложили пошлины против покупателей российской нефти."},{"id":"b005","kind":"paragraph","text":"Для тех, кто платит за импортные товары, поездки и переводы за границу, курс сейчас выгоднее, чем 2 недели назад. На ценах в магазинах это сказывается с задержкой, потому что продавцы закупают товар заранее. Ключевая ставка 14% тоже поддерживает рубль: кредиты дорогие, спрос на импорт сдержан, а рублёвые вклады выгоднее валютных. Экспортёрам и бюджету крепкий рубль невыгоден: с каждого проданного за валюту барреля они получают меньше рублей."},{"id":"b006","kind":"paragraph","text":"Владимир Евстифеев из банка \xabЗенит\xbb ждёт, что к 28 октября доллар может опуститься к 82 рублям. После налогового срока экспортёрам не нужно столько рублей, и их продажи обычно стихают, а Минфин продолжит покупать до 6 ноября. Новый объём покупок Минфин объявит в начале ноября, и он будет зависеть от цены нефти в октябре. Дорогая нефть означает крупные покупки и в ноябре. Её подешевление уменьшит и покупки государства, и выручку экспортёров."},{"id":"b007","kind":"heading","text":"Почему доллар подешевел ниже 83 рублей в октябре 2026 года?"},{"id":"b008","kind":"paragraph","text":"До 28 октября нефтяники платят налоги за сентябрь, а нефтегазовые доходы бюджета в октябре оцениваются примерно в 1 трлн рублей, вдвое больше, чем в сентябре. Для уплаты экспортёры продают валюту. Её предложение превысило покупки государства по бюджетному правилу, и рубль укрепился."},{"id":"b009","kind":"heading","text":"Почему рубль крепнет, если Минфин скупает валюту?"},{"id":"b010","kind":"paragraph","text":"Государство покупает валюту равными частями каждый день, около 12 млрд рублей. Экспортёры продают неравномерно, больше всего перед налоговым сроком. Во второй половине месяца продавцов становится больше, чем покупателей."},{"id":"b011","kind":"heading","text":"Что будет с курсом после 28 октября?"},{"id":"b012","kind":"paragraph","text":"После уплаты налогов экспортёрам не нужно столько рублей, и их продажи обычно сокращаются. Покупки Минфина в нынешнем объёме продолжатся до 6 ноября, а новый объём будет зависеть от цены нефти в октябре."}],"sources":[{"label":"Курс доллара опустился ниже 83 рублей впервые за два месяца","url":"https://www.kommersant.ru/doc/9042314"},{"label":"Курс доллара приблизился к 82,5 рубля","url":"https://www.kommersant.ru/doc/9042203"},{"label":"ЦБ понизил курс доллара","url":"https://lenta.ru/news/2026/10/19/tsb-ponizil-kurs-dollara"},{"label":"Банк России снизил курс доллара на 77 копеек","url":"https://www.vedomosti.ru/finance/news/2026/10/19/1238342-kurs-dollara"},{"label":"Курс доллара США на 8 октября 2026 года","url":"https://ppt.ru/currencies/usd/08-10-2026"},{"label":"Нефтегазовые доходы бюджета РФ вырастут в октябре до 1 трлн рублей","url":"https://ru.themoscowtimes.com/2026/10/15/neftegazovye-dokhody-byudzheta-rf-vyrastut-na-10-v-oktyabre-2625gg-do-1-trln-rub-raschyot-reyter-a208727"},{"label":"Рубль продолжает рост с учётом нефтяной и налоговой поддержки","url":"https://ru.themoscowtimes.com/2026/10/19/rubl-prodolzhaet-rost-s-uchetom-neftyanoy-i-nalogovoy-podderzhki-geopolitiki-a208952"},{"label":"Минфин купит валюту и золото на 279,42 млрд руб. с 7 октября по 6 ноября","url":"https://www.kommersant.ru/doc/9006327"}],"sourceBodySha256":"f25608d7c3546bcf7841b9396fc0c3e8ef4ad41fa20f369f655ea9a55be665d4"}')}}]);